<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import UiButton from '@/components/ui/UiButton.vue'
import UiNotice from '@/components/ui/UiNotice.vue'
import OwnerField from '@/components/owner/OwnerField.vue'
import OccupancyPicker from '@/components/billing/OccupancyPicker.vue'
import InvoiceLines from '@/components/billing/InvoiceLines.vue'
import { useOwnerApi } from '@/composables/useOwnerApi'
import { toApiError } from '@/lib/api'
import { localEventTime } from '@/composables/useOwnerApi'
import { dueDateText } from '@/lib/invoice-controls'
import { previousMonth } from '@/lib/billing'
import { formatMoney } from '@/lib/format'
import { formatDateTime } from '@/lib/notifications'
import type { Occupancy } from '@/types/owner'
import type { Invoice, InvoicePreview } from '@/types/billing'
const route = useRoute(), router = useRouter(), client = useOwnerApi()
const occupancyId = ref<number | null>(Number(route.query.occupancy_id) > 0 ? Number(route.query.occupancy_id) : null), month = ref(previousMonth()), dueDate = ref(''), preview = ref<InvoicePreview | null>(null), occupancy = ref<Occupancy | null>(null), reviewing = ref(false), confirm = ref(false), message = ref(''), representative = ref('')
let alive = true, sequence = 0, detailSequence = 0
const candidates = computed(() => { const end = occupancy.value?.ended_at; return end ? occupancy.value?.members?.filter(item => item.moved_in_at < end && (!item.moved_out_at || item.moved_out_at >= end)) ?? [] : [] })
watch([occupancyId, month], () => { sequence++; preview.value = null; reviewing.value = false; confirm.value = false; message.value = ''; client.clearError() })
watch(occupancyId, async id => { const current = ++detailSequence; occupancy.value = null; representative.value = ''; if (!id) return; try { const result = await client.get<{ data: Occupancy }>(`/occupancies/${id}`); if (alive && current === detailSequence && id === occupancyId.value) occupancy.value = result.data } catch (caught) { if (alive && current === detailSequence) message.value = toApiError(caught).message } }, { immediate: true })
async function calculate() { if (!occupancyId.value || !month.value) return; const current = ++sequence; preview.value = null; reviewing.value = false; confirm.value = false; message.value = ''; try { const result = await client.write<{ data: InvoicePreview }>('post', `/occupancies/${occupancyId.value}/invoices/preview`, { billing_month: month.value }); if (alive && current === sequence) preview.value = result.data } catch { /* Field and request errors remain visible. */ } }
async function issue() { if (!preview.value?.can_issue || !confirm.value || !reviewing.value) return; try { const result = await client.write<{ data: Invoice }>('post', `/occupancies/${preview.value.occupancy_id}/invoices`, { billing_month: preview.value.billing_month, preview_token: preview.value.preview_token, due_date: dueDate.value || null }); await router.push(`/owner/invoices/${result.data.id}?issued=1`) } catch (caught) { reviewing.value = false; confirm.value = false; if (toApiError(caught).status === 409) { preview.value = null; message.value = 'Dữ liệu tính tiền đã thay đổi hoặc tháng đã được phát hành. Hãy xem trước lại; nếu vừa bị mất kết nối, kiểm tra danh sách hóa đơn trước.' } } }
async function supplement() { if (!occupancyId.value || !representative.value) return; try { await client.write('post', `/occupancies/${occupancyId.value}/billing-representative`, { tenant_stay_id: Number(representative.value) }); const result = await client.get<{ data: Occupancy }>(`/occupancies/${occupancyId.value}`); occupancy.value = result.data; message.value = 'Đã bổ sung đại diện lịch sử. Hãy xem trước lại hóa đơn.'; preview.value = null } catch { /* Preserve selection and display backend validation. */ } }
onBeforeUnmount(() => { alive = false; sequence++; detailSequence++ })
</script>
<template><section class="management-page"><RouterLink class="back-link" to="/owner/invoices">← Danh sách hóa đơn</RouterLink><header class="management-header"><div><span class="eyebrow">Xem trước → kiểm tra → phát hành</span><h1>Lập hóa đơn tháng</h1><p>Tiền phòng thu một lần cho nhóm trong tháng. Phí theo phòng được chia theo thời gian sử dụng.</p></div></header><UiNotice v-if="message" tone="warning">{{ message }}</UiNotice><p v-if="client.error.value" class="form-error" role="alert">{{ client.error.value }}</p><div class="record-card form-grid"><fieldset class="form-grid" :disabled="client.busy.value || reviewing"><OccupancyPicker v-model="occupancyId" /><OwnerField v-model="month" label="Tháng tính tiền" name="billing_month" type="month" required :errors="client.errors.value" /></fieldset><label>Hạn thanh toán (không bắt buộc)<input v-model="dueDate" type="date" class="ui-input" :min="localEventTime().slice(0, 10)" :disabled="reviewing || client.busy.value" /><span class="help-text">Để trống: chưa đặt hạn. Hóa đơn chỉ quá hạn sau ngày đã chọn.</span></label><p v-if="client.errors.value.due_date" class="field-error">{{ client.errors.value.due_date[0] }}</p><div class="button-row"><UiButton :loading="client.busy.value" :disabled="!occupancyId || !month || reviewing" @click="calculate">Xem trước hóa đơn</UiButton><RouterLink v-if="occupancyId" class="record-link" :to="`/owner/meters?occupancy_id=${occupancyId}`">Ghi / kiểm tra điện nước</RouterLink></div></div><section v-if="occupancy?.ended_at && !occupancy.representatives?.length" class="record-card" style="margin-top:24px"><h2>Bổ sung đại diện lịch sử</h2><p class="help-text">Chọn người còn cư trú lúc trả phòng. Hệ thống giữ nguyên thời gian thuê và không tự tạo tài khoản.</p><label class="select-field">Người đại diện để lập hóa đơn<select v-model="representative" class="ui-select"><option value="">Chọn thành viên</option><option v-for="member in candidates" :key="member.id" :value="String(member.id)">{{ member.tenant?.full_name }}</option></select></label><UiButton variant="secondary" :loading="client.busy.value" :disabled="!representative" @click="supplement">Xác nhận bổ sung đại diện</UiButton></section><section v-if="preview" class="record-card" style="margin-top:24px"><header><div><h2>{{ reviewing ? 'Xác nhận phát hành hóa đơn' : 'Bản xem trước hóa đơn' }}</h2><p class="help-text">Phòng {{ occupancy?.room.room_number }} · {{ preview.billing_month }}<br />{{ formatDateTime(preview.period_start) }} → {{ formatDateTime(preview.period_end) }}</p></div></header><UiNotice v-if="preview.blockers.length" tone="warning" title="Cần xử lý trước khi phát hành"><ul><li v-for="blocker in preview.blockers" :key="blocker">{{ blocker }}</li></ul></UiNotice><UiNotice v-if="preview.warnings.length" tone="warning"><ul><li v-for="warning in preview.warnings" :key="warning">{{ warning }}</li></ul></UiNotice><RouterLink v-if="preview.existing_invoice_id" class="record-link" :to="`/owner/invoices/${preview.existing_invoice_id}`">Xem hóa đơn đã phát hành</RouterLink><InvoiceLines :items="preview.items" /><dl class="record-facts review-box"><div><dt>Tổng hóa đơn dự kiến</dt><dd><strong>{{ formatMoney(preview.total_amount) }}</strong></dd></div><div><dt>Hạn thanh toán</dt><dd>{{ dueDateText(dueDate) }}</dd></div><div><dt>Quyền xem người thuê</dt><dd>{{ preview.recipient_user_id ? 'Sẽ cấp cho đại diện hợp lệ' : 'Chưa cấp quyền người thuê' }}</dd></div></dl><p class="help-text">Hóa đơn phát hành sẽ khóa các kỳ chỉ số trong tháng. Xác nhận thu tiền là thao tác riêng sau khi thực nhận tiền.</p><div v-if="preview.can_issue && !reviewing" class="button-row"><UiButton :disabled="client.busy.value" @click="reviewing = true">Kiểm tra và phát hành</UiButton></div><template v-if="reviewing"><label class="billing-confirm"><input v-model="confirm" type="checkbox" /> Tôi đã kiểm tra thời gian, chỉ số và các khoản tính tiền.</label><div class="button-row"><UiButton variant="secondary" :disabled="client.busy.value" @click="reviewing = false; confirm = false">Quay lại kiểm tra</UiButton><UiButton :loading="client.busy.value" :disabled="!confirm" @click="issue">Xác nhận phát hành hóa đơn</UiButton></div></template></section></section></template>
<style scoped>.billing-confirm { display:flex;gap:12px;align-items:flex-start;margin:20px 0;font-size:14px; }.billing-confirm input { width:20px;height:20px;accent-color:var(--color-primary);flex-shrink:0; }</style>
